from fastapi import FastAPI, Header, TestClient
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def read_root(my_header: str = Header(None)):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header_rejected():
    # Should be rejected (or rather, not captured in the variable)
    # because convert_underscores=True by default.
    # Wait, if it's not captured, the variable my_header will be None.
    response = client.get("/", headers={"my_header": "value1"})
    assert response.json() == {"my_header": None}

    # Should be accepted if using hyphen
    response = client.get("/", headers={"my-header": "value2"})
    assert response.json() == {"my_header": "value2"}

def test_underscore_header_accepted_when_disabled():
    # We need another endpoint with convert_underscores=False
    pass

app2 = FastAPI()
@app2.get("/")
async def read_root2(my_header: str = Header(None, convert_underscores=False)):
    return {"my_header": my_header}

client2 = TestClient(app2)

def test_underscore_header_accepted_disabled():
    response = client2.get("/", headers={"my_header": "value3"})
    assert response.json() == {"my_header": "value3"}

if __name__ == "__main__":
    try:
        test_underscore_header_rejected()
        print("test_underscore_header_rejected passed")
    except AssertionError as e:
        print(f"test_underscore_header_rejected failed: {e}")

    try:
        test_underscore_header_accepted_disabled()
        print("test_underscore_header_accepted_disabled passed")
    except AssertionError as e:
        print(f"test_underscore_header_accepted_disabled failed: {e}")

